const cfg=JSON.parse(Buffer.from('','base64').toString('utf8'));const role=Number(process.argv[1]||0);if(!Number.isInteger(role)||role<0||role>2)throw Error('ROLE');
console.log('SFFILE_STAGE:'+JSON.stringify({role,pid:process.pid,stage:'ready'}));
async function main(){await test('fixed builtin node:test role '+role,()=>{assert.equal(2+2,4);console.log('SFFILE_POSITIVE:'+role);});const rows=[];
try{rows.push({kind:'positive_read',ok:fs.readFileSync(cfg.positive,'utf8')==='FIXED_READ_CONTROL'});}catch(e){rows.push({kind:'positive_read',ok:false,error:e.code});}
try{fs.readFileSync(cfg.shadow);rows.push({kind:'shadow_read',ok:false,unexpected_access:true});}catch(e){rows.push({kind:'shadow_read',ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}
for(const [index,p]of cfg.writes.entries()){try{fs.writeFileSync(p+'\\unauthorized-role-'+role+'.txt','SYNTHETIC-WRITE',{flag:'wx'});rows.push({kind:'write_'+index,ok:false,unexpected_access:true});}catch(e){rows.push({kind:'write_'+index,ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}}
try{fs.writeFileSync(cfg.shadow,'SYNTHETIC-MUTATION');rows.push({kind:'shadow_write',ok:false,unexpected_access:true});}catch(e){rows.push({kind:'shadow_write',ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}
if(cfg.port)rows.push(await new Promise(resolve=>{let done=false;const socket=require('node:net').connect({host:'127.0.0.1',port:cfg.port});function end(error,connected){if(done)return;done=true;socket.destroy();resolve({kind:'loopback',ok:!connected&&(error==='EACCES'||error==='EPERM'),error,connected});}socket.once('connect',()=>end(null,true));socket.once('error',e=>end(e.code,false));socket.setTimeout(1500,()=>end('ETIMEDOUT',false));}));
if(cfg.externalHost)rows.push(await new Promise(resolve=>{let done=false;const socket=require('node:net').connect({host:cfg.externalHost,port:cfg.externalPort});function end(error,connected){if(done)return;done=true;socket.destroy();resolve({kind:'external_tcp',ok:!connected&&(error==='EACCES'||error==='EPERM'),error,connected});}socket.once('connect',()=>end(null,true));socket.once('error',e=>end(e.code,false));socket.setTimeout(1500,()=>end('ETIMEDOUT',false));}));
for(const [i,p]of cfg.uncPaths.entries()){try{fs.readFileSync(p);rows.push({kind:'unc_read_'+i,ok:false,unexpected_access:true});}catch(e){rows.push({kind:'unc_read_'+i,ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}try{fs.writeFileSync(p,'SYNTHETIC-UNC-WRITE');rows.push({kind:'unc_write_'+i,ok:false,unexpected_access:true});}catch(e){rows.push({kind:'unc_write_'+i,ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}}
for(const [i,p]of cfg.aliasPositive.entries()){try{rows.push({kind:'alias_positive_'+i,ok:fs.readFileSync(p,'utf8')==='FIXED_READ_CONTROL'});}catch(e){rows.push({kind:'alias_positive_'+i,ok:false,error:e.code});}try{fs.writeFileSync(p,'SYNTHETIC-ALIAS-POSITIVE-WRITE');rows.push({kind:'alias_positive_write_'+i,ok:false,unexpected_access:true});}catch(e){rows.push({kind:'alias_positive_write_'+i,ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}}
for(const [i,p]of cfg.aliasNegative.entries()){try{fs.readFileSync(p);rows.push({kind:'alias_read_'+i,ok:false,unexpected_access:true});}catch(e){rows.push({kind:'alias_read_'+i,ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}try{fs.writeFileSync(p,'SYNTHETIC-ALIAS-WRITE');rows.push({kind:'alias_write_'+i,ok:false,unexpected_access:true});}catch(e){rows.push({kind:'alias_write_'+i,ok:e.code==='EACCES'||e.code==='EPERM',error:e.code});}}
let nativeUnc=null;if(cfg.uncPaths.length){const r=cp.spawnSync(cfg.helper,[cfg.nonce,'--unc-only',String(role)],{stdio:'inherit',timeout:5000,windowsHide:true});nativeUnc={status:r.status,signal:r.signal,error:r.error?r.error.code:null};}const diagnosticRows=rows.every(r=>r.ok||(cfg.uncPaths.length&&r.kind.startsWith('unc_')&&r.error==='UNKNOWN'));
let child=null;if(diagnosticRows&&role<2){const r=cp.spawnSync(process.execPath,['-e',process.execArgv[1],String(role+1)],{stdio:'inherit',timeout:cfg.nativeBoundary?12000:8000,windowsHide:true});child={status:r.status,signal:r.signal,error:r.error?r.error.code:null};}
if(diagnosticRows&&role===2&&cfg.privateRegistry){const r=cp.spawnSync(cfg.helper,cfg.nativeBoundary?[cfg.nonce,'--native-boundary']:[cfg.nonce],{stdio:'inherit',timeout:cfg.nativeBoundary?8000:5000,windowsHide:true});child={status:r.status,signal:r.signal,error:r.error?r.error.code:null};}
console.log('SFFILE_REPORT:'+JSON.stringify({probe:'D21_FILE_DESCENDANTS_V1',role,pid:process.pid,rows,child,nativeUnc}));if(rows.some(r=>!r.ok)||((role<2||cfg.privateRegistry)&&(!child||child.status!==0||child.error||child.signal)))process.exitCode=42;}
setTimeout(()=>main().catch(e=>{console.error('SFFILE_FAILURE:'+String(e));process.exitCode=43;}),700);
"

